-- Retain original bytes before applying the two operator-confirmed pressure corrections.
CREATE TABLE measurement_correction (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 measurement_id INT NOT NULL,
 site_id VARCHAR(32) NOT NULL,
 measured_at DATETIME NOT NULL,
 metric_key VARCHAR(50) NOT NULL,
 original_hex VARCHAR(80) NOT NULL,
 corrected_text VARCHAR(10) NOT NULL,
 reason VARCHAR(255) NOT NULL,
 corrected_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 UNIQUE KEY uq_measurement_correction(measurement_id,metric_key,original_hex)
);
INSERT INTO measurement_correction(measurement_id,site_id,measured_at,metric_key,original_hex,corrected_text,reason)
SELECT `index`,siteid,date,'hepres',HEX(hepres),
 CASE siteid WHEN '013' THEN '2.285' ELSE '0.930' END,
 'Operator confirmed pressure correction, 2026-10-21; original bytes retained'
FROM mrtb WHERE (siteid='013' AND date='2026-10-20 12:04:04' AND HEX(hepres)='320E333835')
 OR (siteid='010' AND date='2026-10-21 07:43:04' AND HEX(hepres)='30393330');
UPDATE mrtb m JOIN measurement_correction c ON c.measurement_id=m.`index`
 AND c.site_id=m.siteid AND c.metric_key='hepres' AND c.original_hex=HEX(m.hepres)
 SET m.hepres=c.corrected_text;

-- Keep source strings. Reject embedded controls, split numbers and ambiguous zero-padded integers.
-- Permit existing decimal forms and explicit unit suffixes without stripping characters between digits.
ALTER TABLE mrtb
 MODIFY COLUMN recosi_value DOUBLE AS (CASE WHEN TRIM(`recosi`) REGEXP '^([+-]?([0-9]+[.][0-9]*|[.][0-9]+|0|[1-9][0-9]*))[ ]*(psi|kPa|bar|K|C|°C|°F|%|L/min|l/min|LPM|lpm|Hz|V|A)?$' AND `recosi` NOT REGEXP '[[:cntrl:]]' THEN CASE WHEN CAST(REGEXP_SUBSTR(TRIM(`recosi`), '^[+-]?([0-9]+[.][0-9]*|[.][0-9]+|0|[1-9][0-9]*)') AS DOUBLE)>0 AND CAST(REGEXP_SUBSTR(TRIM(`recosi`), '^[+-]?([0-9]+[.][0-9]*|[.][0-9]+|0|[1-9][0-9]*)') AS DOUBLE) NOT IN (0.001,0.01,0.1) THEN CAST(REGEXP_SUBSTR(TRIM(`recosi`), '^[+-]?([0-9]+[.][0-9]*|[.][0-9]+|0|[1-9][0-9]*)') AS DOUBLE) ELSE NULL END ELSE NULL END) PERSISTENT,
 MODIFY COLUMN recosi_unmeasured TINYINT(1) AS (CASE WHEN TRIM(`recosi`) REGEXP '^([+-]?([0-9]+[.][0-9]*|[.][0-9]+|0|[1-9][0-9]*))[ ]*(psi|kPa|bar|K|C|°C|°F|%|L/min|l/min|LPM|lpm|Hz|V|A)?$' AND `recosi` NOT REGEXP '[[:cntrl:]]' THEN CASE WHEN CAST(REGEXP_SUBSTR(TRIM(`recosi`), '^[+-]?([0-9]+[.][0-9]*|[.][0-9]+|0|[1-9][0-9]*)') AS DOUBLE)<=0 OR CAST(REGEXP_SUBSTR(TRIM(`recosi`), '^[+-]?([0-9]+[.][0-9]*|[.][0-9]+|0|[1-9][0-9]*)') AS DOUBLE) IN (0.001,0.01,0.1) THEN 1 ELSE 0 END ELSE 1 END) PERSISTENT,
 MODIFY COLUMN coldtp_value DOUBLE AS (CASE WHEN TRIM(`coldtp`) REGEXP '^([+-]?([0-9]+[.][0-9]*|[.][0-9]+|0|[1-9][0-9]*))[ ]*(psi|kPa|bar|K|C|°C|°F|%|L/min|l/min|LPM|lpm|Hz|V|A)?$' AND `coldtp` NOT REGEXP '[[:cntrl:]]' THEN CASE WHEN CAST(REGEXP_SUBSTR(TRIM(`coldtp`), '^[+-]?([0-9]+[.][0-9]*|[.][0-9]+|0|[1-9][0-9]*)') AS DOUBLE)>0 AND CAST(REGEXP_SUBSTR(TRIM(`coldtp`), '^[+-]?([0-9]+[.][0-9]*|[.][0-9]+|0|[1-9][0-9]*)') AS DOUBLE) NOT IN (0.001,0.01,0.1) THEN CAST(REGEXP_SUBSTR(TRIM(`coldtp`), '^[+-]?([0-9]+[.][0-9]*|[.][0-9]+|0|[1-9][0-9]*)') AS DOUBLE) ELSE NULL END ELSE NULL END) PERSISTENT,
